import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

test('invalid quantity exits with status 2 and reports the error on stderr', () => {
  const command = fileURLToPath(new URL('../src/quantity.ts', import.meta.url));
  const result = spawnSync(process.execPath, [command, '0'], { encoding: 'utf8' });

  assert.ifError(result.error);
  assert.equal(result.status, 2);
  assert.equal(result.stdout, '');
  assert.equal(result.stderr, 'Invalid quantity\n');
});
